BEGIN READ ONLY;SET LOCAL statement_timeout='15s';
SELECT jsonb_build_object('db',current_database(),'role',current_user,'readOnly',current_setting('transaction_read_only'),
 'ownerBypassRls',(SELECT rolbypassrls FROM pg_roles WHERE rolname=current_user),
 'functions',(SELECT jsonb_agg(jsonb_build_object('identity',p.oid::regprocedure::text,'md5',md5(replace(pg_get_functiondef(p.oid),chr(13),'')),'owner',pg_get_userbyid(p.proowner),'definer',p.prosecdef,'config',p.proconfig,'acl',p.proacl,'publicGrants',(SELECT count(*) FROM aclexplode(p.proacl) a WHERE a.grantee=0),'nonownerGrants',(SELECT count(*) FROM aclexplode(p.proacl) a WHERE a.grantee<>p.proowner))) FROM pg_proc p WHERE p.oid IN(to_regprocedure('public.create_org_with_store(text,text)'),to_regprocedure('public.create_org_with_store_currency_v1(uuid,text,text,text,text,boolean)'),to_regprocedure('public.create_org_with_store_currency_tzs_v1(uuid,text,text,text,text,boolean)'),to_regprocedure('backend_core.consume_tzs_canary_org_permit(uuid)'))),
 'apiExec',(SELECT jsonb_agg(jsonb_build_object('role',r.rolname,'function',p.oid::regprocedure::text,'execute',has_function_privilege(r.oid,p.oid,'EXECUTE'))) FROM pg_roles r CROSS JOIN pg_proc p WHERE r.rolname IN('anon','authenticated','service_role','authenticator','cli_login_postgres') AND p.oid IN(to_regprocedure('public.create_org_with_store_currency_v1(uuid,text,text,text,text,boolean)'),to_regprocedure('public.create_org_with_store_currency_tzs_v1(uuid,text,text,text,text,boolean)'),to_regprocedure('backend_core.consume_tzs_canary_org_permit(uuid)'))),
 'tables',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',c.relname,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'force',c.relforcerowsecurity,'nonownerGrants',(SELECT count(*) FROM aclexplode(c.relacl) a WHERE a.grantee<>c.relowner))),'[]'::jsonb) FROM pg_class c WHERE c.relnamespace='backend_core'::regnamespace AND c.relname IN('tzs_onboarding_rollout','tzs_onboarding_allowlist','tzs_onboarding_rollout_audit','tzs_onboarding_canary_quota','tzs_canary_creation_permits')),
 'enabled',(SELECT enabled FROM backend_core.tzs_onboarding_rollout WHERE singleton),
 'enrolled',(SELECT count(*) FROM backend_core.tzs_onboarding_allowlist),
 'quotaExists',to_regclass('backend_core.tzs_onboarding_canary_quota') IS NOT NULL,
 'permitsExist',to_regclass('backend_core.tzs_canary_creation_permits') IS NOT NULL) metadata;
ROLLBACK;
